INSERT INTO `chat_message` VALUES (1,1,'user','制度由哪个部门负责解释？',NULL,'2026-11-11 18:25:10',1),(2,2,'user','制度由哪个部门负责解释？',NULL,'2026-11-11 18:25:23',1),(3,2,'assistant','制度由信息技术部负责解释，出处为【参考资料】[2]。','[{\"documentId\":13,\"chunkIndex\":2,\"fileName\":\"zhihui_step4_isolation.txt\",\"score\":0.5244876742362976,\"content\":\"来源文档名称与段落位置。引用他人材料形成新文档时，应在文末注明来源。对于检索结果存在明显偏差的情况，员工可提交纠错反馈，由知识管理员在三个工作日内核实并修正索引数据。纠错记录纳入季度知识运营报告。\\n\\n第五章 权限与安全。知识中枢采用基于角色的访问控制模型，角色分为普通员工、部门管理员与系统管理员。普通员工仅可查看与自己相关的文档及公开级材料，部门管理员可查看本部门全部材料，系统管理员可查看全量数据并执行删除操作。所有删除均为逻辑删除，数据在后台保留九十天后由定时任务物理清理。向量数据与原文数据的删除必须保持同步，不得出现只删原文不删向量的情况。\\n\\n第六章 考核与附则。知识贡献情况纳入年度绩效考核的加分项，按被引用次数与材料质量综合评定。本说明由信息技术部负责解释，自发布之日起施行。原有相关规定与本说明不一致的，以本说明为准。\"},{\"documentId\":13,\"chunkIndex\":0,\"fileName\":\"zhihui_step4_isolation.txt\",\"score\":0.5100270509719849,\"content\":\"企业知识管理制度说明\\n\\n第一章 总则。为规范公司内部知识资产的采集、存储、共享与销毁流程，提升组织经验沉淀效率，特制定本说明。本说明适用于集团总部及各下属分子公司的全体在职员工，外包人员参照执行。知识资产包括但不限于技术文档、项目复盘、操作手册、会议纪要与培训材料。所有知识资产在入库前须完成密级标注，密级分为公开、内部、秘密三级，跨级访问须经知识管理员审批。\\n\\n第二章 采集与提交。员工应在项目里程碑完成后五个工作日内，将可复用的经验材料整理成文并提交至知识中枢。提交时须填写标题、摘要、适用范围与关键词四项元数据。摘要不超过两百字，需概括材料的核心结论与适用场景。关键词不少于三个，用于后续检索召回。对于涉及客户信息的材料，提交前必须完成脱敏处理，去除姓名、联系方式与合同金额等敏感字段。\"},{\"documentId\":13,\"chunkIndex\":1,\"fileName\":\"zhihui_step4_isolation.txt\",\"score\":0.4432142674922943,\"content\":\"围与关键词四项元数据。摘要不超过两百字，需概括材料的核心结论与适用场景。关键词不少于三个，用于后续检索召回。对于涉及客户信息的材料，提交前必须完成脱敏处理，去除姓名、联系方式与合同金额等敏感字段。\\n\\n第三章 存储与索引。知识中枢对提交的材料统一进行文本解析与切片处理，切片长度控制在五百字符左右，相邻切片保留百分之二十的重叠内容，以降低语义割裂带来的检索损失。每个切片生成一条向量表示，写入向量库并保留原文与来源文档的对应关系。原始文件同时归档至对象存储，保留期限不少于三年。任何切片都不得脱离来源文档单独对外提供。\\n\\n第四章 检索与使用。员工可通过自然语言提问的方式检索知识库，系统返回与问题最相关的前若干条切片，并附上来源文档名称与段落位置。引用他人材料形成新文档时，应在文末注明来源。对于检索结果存在明显偏差的情况，员工可提交纠错反馈，由知识管理员在三个工作日内核实并修正索引数据。纠错记录纳入季度知识运营报告。\"}]','2026-11-11 18:25:24',1),(4,3,'user','制度由哪个部门负责解释？',NULL,'2026-11-11 18:25:32',1),(5,3,'assistant','制度由信息技术部负责解释[2]。','[{\"documentId\":13,\"chunkIndex\":2,\"fileName\":\"zhihui_step4_isolation.txt\",\"score\":0.5251513123512268,\"content\":\"来源文档名称与段落位置。引用他人材料形成新文档时，应在文末注明来