INSERT INTO `document` VALUES (1,'a.txt','C:\\Users\\28673.LAPTOP-3SPUPN2L\\AppData\\Local\\Temp\\zhihui-uploads\\3f1bc096d0fd4bf4b44edf1bbbb5dd31.txt',33,'txt','﻿智汇测试文档 第一行\r\n','SUCCESS',NULL,4,'2026-11-03 00:22:07','2026-11-03 00:22:07',0),(2,'a.txt','C:\\Users\\28673.LAPTOP-3SPUPN2L\\AppData\\Local\\Temp\\zhihui-uploads\\267a90ad0bd447a29f92760a242c7be8.txt',33,'txt','﻿智汇测试文档 第一行\r\n','SUCCESS',NULL,4,'2026-11-03 00:22:07','2026-11-03 00:22:07',0),(3,'bad.pdf','C:\\Users\\28673.LAPTOP-3SPUPN2L\\AppData\\Local\\Temp\\zhihui-uploads\\8dbbd272eb0c4dfb927a9d3b46775302.pdf',21,'pdf',NULL,'FAILED','解析失败：Error: End-of-File, expected line at offset 21',4,'2026-11-03 00:22:07','2026-11-03 00:22:07',0),(4,'step4_seed.txt','C:/Users/28673.LAPTOP-3SPUPN2L/AppData/Local/Temp/zhihui-uploads/3f1bc096d0fd4bf4b44edf1bbbb5dd31.txt',9,'txt','step4 detail content seed','SUCCESS',NULL,5,'2026-11-03 01:25:05','2026-11-03 01:25:31',1),(5,'111.txt','D:\\ai\\uploads\\db5ad4901bbb4746a7861b9eafd7dae9.txt',3,'txt','111','SUCCESS',NULL,4,'2026-11-03 01:38:54','2026-11-03 01:38:54',0),(6,'111.txt','D:\\ai\\uploads\\e5f9aa91a890487abbb15f4f35ddaf3e.txt',3051,'txt','111深秋的清晨总带着几分清冽的凉意，天刚蒙蒙亮时，巷口的早餐铺就已经飘出了温热的香气。白雾从蒸笼里慢悠悠地涌出来，裹着小麦与黄豆的清甜，在微凉的空气里散开，成了整条巷子最早的烟火。\r\n\r\n老板是一对中年夫妇，男人负责揉面、蒸包，女人负责盛粥、招呼客人。男人话不多，手上的动作却极利落，面团在他手里翻折、按压，不过片刻就变成一个个圆润饱满的包子生坯，整齐码在蒸笼里。女人性子爽朗，看见熟客就笑着打招呼，记得张大爷要少放辣的豆腐脑，记得上学的孩子要皮薄馅多的青菜包，连谁习惯打包带走、谁爱坐下来慢慢吃，都记得清清楚楚。\r\n\r\n我常去那里买早餐。最爱的是一碗热豆浆配两个鲜肉包，豆浆是现磨的，醇厚香浓，喝下去从喉咙暖到胃里；包子咬开有鲜美的汤汁，面皮暄软，肉馅紧实，是踏踏实实的家常味道。铺子不大，只有几张简易的桌子，却总是收拾得干干净净，塑料凳擦得发亮，连装醋的小瓶子都摆得整整齐齐。\r\n\r\n来吃早餐的人形形色色。有背着书包的学生，急匆匆扒完一碗粥就往学校赶；有晨练回来的老人，慢悠悠地就着咸菜喝豆浆，和老板唠两句家常；有穿着工装的上班族，打包好早餐就一路小跑着去赶公交。每个人都带着各自的生活节奏，却在这小小的早餐铺里，共享着一段温热的清晨时光。\r\n\r\n有一次下着小雨，我出门时忘了带伞，跑到铺子时头发已经湿了大半。女人见了，连忙从柜台下抽出纸巾递过来，又给我盛了碗比往常更热的豆浆，说：“暖暖身子，别急。” 那天我坐在铺子里，看着雨丝落在门前的青石板上，听着蒸笼发出的轻微咕嘟声，心里忽然生出一种安稳的感动。\r\n\r\n后来我才知道，这对夫妇在这里开了快十年。每天凌晨三点就起床备料，揉面、调馅、磨豆浆，一年四季从不间断。有人问他们累不累，男人只是憨厚地笑，女人则说：“大家早上能吃口热的，我们也踏实。” 没有什么宏大的理想，只是把一件小事认认真真做了十年，把一份温热递到每一个赶路人手里。\r\n\r\n我们总在追寻盛大的风景与耀眼的成就，却常常忽略了身边这些平凡的温暖。一个认真做包子的清晨，一碗恰到好处的热豆浆，一句随口的关心，这些细碎的、不起眼的瞬间，恰恰构成了生活最柔软的底色。就像巷口的早餐铺，它不显眼，也不华丽，却在每个清晨准时亮起灯，用烟火气温暖着整条巷子。\r\n\r\n走出巷子时，天已经大亮了。阳光穿过树叶的缝隙落下来，在地上投下斑驳的光影。手里的早餐还带着余温，心里也装着满满的暖意。原来最动人的生活，从来都不在远方，就在这一粥一饭的烟火里，在每个普通人认真生活的模样里。','SUCCESS',NULL,4,'2026-11-03 22:33:02','2026-11-03 22:33:02',0),(7,'111.txt','D:\\ai\\uploads\\46f1914ae9954be4a2193f9efaa4f89c.txt',3051,'txt','111深秋的清晨总带着几分清冽的凉意，天刚蒙蒙亮时，巷口的早餐铺就已经飘出了温热的香气。白雾从蒸笼里慢悠悠地涌出来，裹着小麦与黄豆的清甜，在微凉的空气里散开，成了整条巷子最早的烟火。\r\n\r\n老板是一对中年夫妇，男人负责揉面、蒸包，女人负责盛粥、招呼客人。男人话不多，手上的动作却极利落，面团在他手里翻折、按压，不过片刻就变成一个个圆润饱满的包子生坯，整齐码在蒸笼里。女人性子爽朗，看见熟客就笑着打招呼，记得张大爷要少放辣的豆腐脑，记得上学的孩子要皮薄馅多的青菜包，连谁习惯打包带走、谁爱坐下来慢慢吃，都记得清清楚楚。\r\n\r\n我常去那里买早餐。最爱的是一碗热豆浆配两个鲜肉包，豆浆是现磨的，醇厚香浓，喝下去从喉咙暖到胃里；包子咬开有鲜美的汤汁，面皮暄软，肉馅紧实，是踏踏实实的家常味道。铺子不大，只有几张简易的桌子，却总是收拾得干干净净，塑料凳擦得发亮，连装醋的小瓶子都摆得整整齐齐。\r\n\r\n来吃早餐的人形形色色。有背着书包的学生，急匆匆扒完一碗粥就往学校赶；有晨练回来的老人，慢悠悠地就着咸菜喝豆浆，和老板唠两句家常；有穿着工装的上班族，打包好早餐就一路小跑着去赶公交。每个人都带着各自的生活节奏，却在这小小的早餐铺里，共享着一段温热的清晨时光。\r\n\r\n有一次下着小雨，我出门时忘了带伞，跑到铺子时头发已经湿了大半。女人见了，连忙从柜台下抽出纸巾递过来，又给我盛了碗比往常更热的豆浆，说：“暖暖身子，别急。” 那天我坐在铺子里，看着雨丝落在门前的青石板上，听着蒸笼发出的轻微咕嘟声，心里忽然生出一种安稳的感动。\r\n\r\n后来我才知道，这对夫妇在这里开了快十年。每天凌晨三点就起床备料，揉面、调馅、磨豆浆，一年四季从不间断。有人问他们累不累，男人只是憨厚地笑，女人则说：“大家早上能吃口热的，我们也踏实。” 没有什么宏大的理想，只是把一件小事认认真真做了十年，把一份温热递到每一个赶路人手里。\r\n\r\n我们总在追寻盛大的风景与耀眼的成就，却常常忽略了身边这些平凡的温暖。一个认真做包子的清晨，一碗恰到好处的热豆浆，一句随口的关心，这些细碎的、不起眼的瞬间，恰恰构成了生活最柔软的底色。就像巷口的早餐铺，它不显眼，也不华丽，却在每个清晨准时亮起灯，用烟火气温暖着整条巷子。\r\n\r\n走出巷子时，天已经大亮了。阳光穿过树叶的缝隙落下来，在地上投下斑驳的光影。手里的早餐还带着余温，心里也装着满满的暖意。原来最动人的生活，从来都不在远方，就在这一粥一饭的烟火里，在每个普通人认真生活的模样里。','SUCCESS',NULL,4,'2026-11-10 22:06:42','2026-11-10 22:06:42',0),(8,'zhihui_step4_isolation.txt','D:\\ai\\uploads\\dbade710b5de4163878e2d96cf0cf1cc.txt',2743,'txt','企业知识管理制度说明\n\n第一章 总则。为规范公司内部知识资产的采集、存储、共享与销毁流程，提升组织经验沉淀效率，特制定本说明。本说明适用于集团总部及各下属分子公司的全体在职员工，外包人员参照执行。知识资产包括但不限于技术文档、项目复盘、操作手册、会议纪要与培训材料。所有知识资产在入库前须完成密级标注，密级分为公开、内部、秘密三级，跨级访问须经知识管理员审批。\n\n第二章 采集与提交。员工应在项目里程碑完成后五个工作日内，将可复用的经验材料整理成文并提交至知识中枢。提交时须填写标题、摘要、适用范围与关键词四项元数据。摘要不超过两百字，需概括材料的核心结论与适用场景。关键词不少于三个，用于后续检索召回。对于涉及客户信息的材料，提交前必须完成脱敏处理，去除姓名、联系方式与合同金额等敏感字段。\n\n第三章 存储与索引。知识中枢对提交的材料统一进行文本解析与切片处理，切片长度控制在五百字符左右，相邻切片保留百分之二十的重叠内容，以降低语义割裂带来的检索损失。每个切片生成一条向量表示，写入向量库并保留原文与来源文档的对应关系。原始文件同时归档至对象存储，保留期限不少于三年。任何切片都不得脱离来源文档单独对外提供。\n\n第四章 检索与使用。员工可通过自然语言提问的方式检索知识库，系统返回与问题最相关的前若干条切片，并附上来源文档名称与段落位置。引用他人材料形成新文档时，应在文末注明来源。对于检索结果存在明显偏差的情况，员工可提交纠错反馈，由知识管理员在三个工作日内核实并修正索引数据。纠错记录纳入季度知识运营报告。\n\n第五章 权限与安全。知识中枢采用基于角色的访问控制模型，角色分为普通员工、部门管理员与系统管理员。普通员工仅可查看与自己相关的文档及公开级材料，部门管理员可查看本部门全部材料，系统管理员可查看全量数据并执行删除操作。所有删除均为逻辑删除，数据在后台保留九十天后由定时任务物理清理。向量数据与原文数据的删除必须保持同步，不得出现只删原文不删向量的情况。\n\n第六章 考核与附则。知识贡献情况纳入年度绩效考核的加分项，按被引用次数与材料质量综合评定。本说明由信息技术部负责解释，自发布之日起施行。原有相关规定与本说明不一致的，以本说明为准。\n','SUCCESS',NULL,4,'2026-11-10 22:11:33','2026-11-10 23:25:48',1),(9,'111.txt','D:\\ai\\uploads\\87a6fe34c90e4671b578cb8b682a0860.txt',3051,'txt','111深秋的清晨总带着几分清冽的凉意，天刚蒙蒙亮时，巷口的早餐铺就已经飘出了温热的香气。白雾从蒸笼里慢悠悠地涌出来，裹着小麦与黄豆的清甜，在微凉的空气里散开，成了整条巷子最早的烟火。\r\n\r\n老板是一对中年夫妇，男人负责揉面、蒸包，女人负责盛粥、招呼客人。男人话不多，手上的动作却极利落，面团在他手里翻折、按压，不过片刻就变成一个个圆润饱满的包子生坯，整齐码在蒸笼里。女人性子爽朗，看见熟客就笑着打招呼，记得张大爷要少放辣的豆腐脑，记得上学的孩子要皮薄馅多的青菜包，连谁习惯打包带走、谁爱坐下来慢慢吃，都记得清清楚楚。\r\n\r\n我常去那里买早餐。最爱的是一碗热豆浆配两个鲜肉包，豆浆是现磨的，醇厚香浓，喝下去从喉咙暖到胃里；包子咬开有鲜美的汤汁，面皮暄软，肉馅紧实，是踏踏实实的家常味道。铺子不大，只有几张简易的桌子，却总是收拾得干干净净，塑料凳擦得发亮，连装醋的小瓶子都摆得整整齐齐。\r\n\r\n来吃早餐的人形形色色。有背着书包的学生，急匆匆扒完一碗粥就往学校赶；有晨练回来的老人，慢悠悠地就着咸菜喝豆浆，和老板唠两句家常；有穿着工装的上班族，打包好早餐就一路小跑着去赶公交。每个人都带着各自的生活节奏，却在这小小的早餐铺里，共享着一段温热的清晨时光。\r\n\r\n有一次下着小雨，我出门时忘了带伞，跑到铺子时头发已经湿了大半。女人见了，连忙从柜台下抽出纸巾递过来，又给我盛了碗比往常更热的豆浆，说：“暖暖身子，别急。” 那天我坐在铺子里，看着雨丝落在门前的青石板上，听着蒸笼发出的轻微咕嘟声，心里忽然生出一种安稳的感动。\r\n\r\n后来我才知道，这对夫妇在这里开了快十年。每天凌晨三点就起床备料，揉面、调馅、磨豆浆，一年四季从不间断。有人问他们累不累，男人只是憨厚地笑，女人则说：“大家早上能吃口热的，我们也踏实。” 没有什么宏大的理想，只是把一件小事认认真真做了十年，把一份温热递到每一个赶路人手里。\r\n\r\n我们总在追寻盛大的风景与耀眼的成就，却常常忽略了身边这些平凡的温暖。一个认真做包子的清晨，一碗恰到好处的热豆浆，一句随口的关心，这些细碎的、不起眼的瞬间，恰恰构成了生活最柔软的底色。就像巷口的早餐铺，它不显眼，也不华丽，却在每个清晨准时亮起灯，用烟火气温暖着整条巷子。\r\n\r\n走出巷子时，天已经大亮了。阳光穿过树叶的缝隙落下来，在地上投下斑驳的光影。手里的早餐还带着余温，心里也装着满满的暖意。原来最动人的生活，从来都不在远方，就在这一粥一饭的烟火里，在每个普通人认真生活的模样里。','SUCCESS',NULL,4,'2026-11-11 16:20:10','2026-11-11 16:20:10',0),(10,'zhihui_step4_isolation.txt','D:\\ai\\uploads\\a587b41197b34218b8dcceef52c36673.txt',2743,'txt','企业知识管理制度说明\n\n第一章 总则。为规范公司内部知识资产的采集、存储、共享与销毁流程，提升组织经验沉淀效率，特制定本说明。本说明适用于集团总